// Confronta i modelli nuovi del sito con quelli già visti. La prima volta li segna tutti come visti, senza mail.
// La memoria resta solo quando il flusso è ATTIVO: le prove a mano con «Esegui» non la salvano.
const memoria = $getWorkflowStaticData('global');
const d = $input.first().json;
const nuovi = d.nuovi || [];
const primaVolta = !Array.isArray(memoria.visti);
const visti = new Set(memoria.visti || []);
const arrivati = nuovi.filter((m) => !visti.has(m.nome));
memoria.visti = [...new Set([...visti, ...nuovi.map((m) => m.nome)])].slice(-500);
if (primaVolta || !arrivati.length) return [];
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const riga = (m) => {
  const b = m.hf?.b ? `${m.hf.b} B parametri` : 'dimensione non pubblicata';
  const gb = m.hf?.b ? `, circa ${Math.round(m.hf.b * 0.606 + 2.7)} GB a 4 bit` : '';
  const dove = m.hf?.repo ? `<a href="https://huggingface.co/${esc(m.hf.repo)}">Hugging Face</a>` : m.or ? 'API gratis su OpenRouter' : '';
  return `<li><b>${esc(m.nome)}</b> di ${esc(m.org || '?')}, uscito il ${esc(m.creato || '?')}: ${b}${gb}. ${dove}</li>`;
};
return [{ json: {
  oggetto: `FreeLLMArena: ${arrivati.length} modell${arrivati.length === 1 ? 'o gratis nuovo' : 'i gratis nuovi'}`,
  html: `<p>Entrati nel sito dall'ultimo controllo:</p><ul>${arrivati.map(riga).join('')}</ul><p>Il video del primo esce da solo su GitHub dopo l'aggiornamento dei dati. Elenco completo: <a href="https://freellmarena.com/#new">freellmarena.com</a></p>`
} }];
